window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8c2686c08b14a6fd"]={"versions": [{"id": "FIG-8c2686c08b14a6fd", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Dekompositionsbaum (FODA-Notation gemäß AUTOSAR Feature Modeling).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation (<code>FO_TR_Features</code>, R24-11). Das Diagramm definiert die funktionale Dekomposition der plattformübergreifenden (Foundation, Classic Platform, Adaptive Platform) Entwicklungs- und Diagnoseinfrastruktur unterhalb der Standardisierungsdomäne <strong>Development</strong> (<code>FO_TR_FEAT_00111</code>).</li>\n<li><strong>Zweck:</strong> Bereitstellung standardisierter Konzepte für Laufzeitbeobachtung, Messdatenerfassung, Parameteranpassung und Leistungsanalyse während des Entwicklungs- und Absicherungszyklus eines Steuergeräts (ECU / Machine).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzel-Feature (Parent):</strong></li>\n<li><code>FO_TR_FEAT_00111</code>: <strong>Development</strong> – Übergreifendes Sammel-Feature für entwicklungsbegleitende Dienste, Schnittstellen und Tool-Interaktionen.</li>\n<li><strong>Kind-Features (Sub-Features):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>FO_TR_FEAT_00120</code>: <strong>Measurement_and_Calibration</strong> – Laufzeitzugriff auf interne Variablen und Kalibrierparameter (typisch via XCP, A2L/ASAP2, RTE-Hooks, BSW-Interna).</li>\n<li><code>FO_TR_FEAT_00117</code>: <strong>Debugging</strong> – Interaktive Fehlersuche, Haltepunkte, Registerinspektion und On-Chip-Debugger-Unterstützung (z. B. JTAG/CoreSight, Core-Dumps, Det/Exception-Handler).</li>\n<li><code>FO_TR_FEAT_00112</code>: <strong>Logging</strong> – Strukturierte Protokollierung von Betriebs- und Diagnosedaten zur Laufzeit (z. B. Diagnostic Log and Trace [DLT], <code>ara::log</code> in AP).</li>\n<li><code>FO_TR_FEAT_00115</code>: <strong>Tracing_and_Profiling</strong> – Nicht-invasive bzw. minimal-invasive Aufzeichnung von Eventfolgen, Funktionslaufzeiten und Stackauslastungen (z. B. über ARTI / AUTOSAR Run-Time Interface, Nexus, SystemView).</li>\n<li><code>FO_TR_FEAT_00119</code>: <strong>Timing_Analysis</strong> – Erfassung und Validierung des zeitlichen Systemverhaltens (z. B. Task-Laufzeiten, Event-Ketten, Jitter, End-to-End-Latenzen gemäß AUTOSAR TIMEX).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Beziehungssemantik & Kardinalitäten:</strong></li>\n<li><strong>Optionale Sub-Features:</strong> Alle fünf Kanten enden an den Kind-Elementen mit einem ungefüllten Kreis (<em>hollow circle</em>). Dies spezifiziert eine Kardinalität von <code>[0..1]</code> pro Sub-Feature relativ zum Parent-Feature.</li>\n<li><strong>Unabhängige Kombinierbarkeit:</strong> Es liegen keine wechselseitigen Ausschlusskanten (XOR) oder erzwungenen Bündelungen (OR) vor; jedes Feature kann je nach Plattform-, Tool- und Projektanforderung unabhängig voneinander aktiviert oder ausgelassen werden.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Feature-Variabilitätsmodell handelt, existiert kein sequenzieller Kontrollfluss. Die funktionale Laufzeitkopplung der dekomponierten Features gliedert sich wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Instrumentierung & Stimulierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>BSW/OS-Hooks und Compiler-Flags triggern synchron <code>Tracing_and_Profiling</code> sowie <code>Timing_Analysis</code>.</li>\n<li>Applikationscode und BSW rufen über APIs synchron Logging-Schnittstellen (z. B. <code>Dlt_SendLogMessage</code> / <code>ara::log</code>) auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Messung & Parametrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchrone XCP-DAQs/ODTs (<code>Measurement_and_Calibration</code>) tasten Variablen getriggert über OS-Raster (z. B. 1ms, 10ms) ab oder führen synchrone Parametermodifikationen über Page-Switching/Emulation aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trace- und Datenexport:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weiterleitung gepufferter Daten über Kommunikationsbusse (Ethernet/SOME/IP, CAN) oder dedizierte Traceschnittstellen an externe Kalibrier-/Timing-Tools.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Plattform-Allokation:</strong></li>\n<li><strong>Classic Platform (CP):</strong> Realisierung über BSW-Module wie <code>Xcp</code>, <code>Dlt</code>, <code>Det</code>, <code>Mcu</code> sowie OS-Hooks (<code>PreTaskHook</code>, <code>PostTaskHook</code>) und ARTI-Instrumentation.</li>\n<li><strong>Adaptive Platform (AP):</strong> Realisierung primär über Functional Clusters (<code>ara::log</code>, ARTI/AP Execution Management Tracing, Core Dump Handling).</li>\n<li><strong>Footprint & Schedulability (SOP vs. DEV):</strong></li>\n<li>Entwicklungs-Features verursachen signifikanten Speicher- (RAM/ROM) und Laufzeit-Overhead sowie Intrusion-Effekte (Probe-Effect).</li>\n<li>Konfiguration muss über Pre-Compile-Schalter (<code>#define DLT_DEV_ERROR_DETECT STD_OFF</code>, Weglassen von XCP-Treibern) für Serien-Builds (SOP) vollständig deaktivierbar sein.</li>\n<li><strong>Security & Safety:</strong></li>\n<li>Kalibrier-, Debugging- und Logging-Interfaces exponieren ECU-Interne. Für Serienstände müssen Hardware-Debug-Ports (JTAG/SWD) physisch/elektronisch gesperrt und Protokolle (<code>FO_TR_FEAT_00120</code>) durch Security Access (Seed & Key) abgesichert werden.</li>\n</ul>"}, {"id": "FIG-c5336c177608114a", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Feature-Modell / Feature-Dekompositionsbaum (FODA-Notation gemäß AUTOSAR Feature Modeling).</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR Foundation (<code>FO_TR_Features</code>, R24-11). Das Diagramm definiert die funktionale Dekomposition der plattformübergreifenden (Foundation, Classic Platform, Adaptive Platform) Entwicklungs- und Diagnoseinfrastruktur unterhalb der Standardisierungsdomäne <strong>Development</strong> (<code>FO_TR_FEAT_00111</code>).</li>\n<li><strong>Zweck:</strong> Bereitstellung standardisierter Konzepte für Laufzeitbeobachtung, Messdatenerfassung, Parameteranpassung und Leistungsanalyse während des Entwicklungs- und Absicherungszyklus eines Steuergeräts (ECU / Machine).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Wurzel-Feature (Parent):</strong></li>\n<li><code>FO_TR_FEAT_00111</code>: <strong>Development</strong> – Übergreifendes Sammel-Feature für entwicklungsbegleitende Dienste, Schnittstellen und Tool-Interaktionen.</li>\n<li><strong>Kind-Features (Sub-Features):</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><code>FO_TR_FEAT_00269</code>: <strong>Bus_Mirroring</strong> – Spiegelung von Buskommunikation (z. B. CAN, LIN, FlexRay, Ethernet) auf Diagnoseschnittstellen oder Logging-Ports zur externen Netzwerkanalyse.</li>\n<li><code>FO_TR_FEAT_00263</code>: <strong>ECU_Data_Collection</strong> – Mechanismen zur zyklischen oder ereignisbasierten Erfassung und Aggregation interner Steuergerätezustände und Diagnosedaten.</li>\n<li><code>FO_TR_FEAT_00117</code>: <strong>Debugging</strong> – Interaktive Fehlersuche, Haltepunkte, Registerinspektion und On-Chip-Debugger-Unterstützung (z. B. JTAG/CoreSight, Core-Dumps, Det/Exception-Handler).</li>\n<li><code>FO_TR_FEAT_00112</code>: <strong>Logging</strong> – Strukturierte Protokollierung von Betriebs- und Diagnosedaten zur Laufzeit (z. B. Diagnostic Log and Trace [DLT], <code>ara::log</code> in AP).</li>\n<li><code>FO_TR_FEAT_00115</code>: <strong>Tracing_and_Profiling</strong> – Nicht-invasive bzw. minimal-invasive Aufzeichnung von Eventfolgen, Funktionslaufzeiten und Stackauslastungen (z. B. über ARTI / AUTOSAR Run-Time Interface, Nexus, SystemView).</li>\n<li><code>FO_TR_FEAT_00120</code>: <strong>Measurement_and_Calibration</strong> – Laufzeitzugriff auf interne Variablen und Kalibrierparameter (typisch via XCP, A2L/ASAP2, RTE-Hooks, BSW-Interna).</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Beziehungssemantik & Kardinalitäten:</strong></li>\n<li><strong>Optionale Sub-Features:</strong> Alle sechs Kanten enden an den Kind-Elementen mit einem ungefüllten Kreis (<em>hollow circle</em>). Dies spezifiziert eine Kardinalität von <code>[0..1]</code> pro Sub-Feature relativ zum Parent-Feature.</li>\n<li><strong>Unabhängige Kombinierbarkeit:</strong> Es liegen keine wechselseitigen Ausschlusskanten (XOR) oder erzwungenen Bündelungen (OR) vor; jedes Feature kann je nach Plattform-, Tool- und Projektanforderung unabhängig voneinander aktiviert oder ausgelassen werden.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\"><em>Da es sich um ein statisches Feature-Variabilitätsmodell handelt, existiert kein sequenzieller Kontrollfluss. Die funktionale Laufzeitkopplung der dekomponierten Features gliedert sich wie folgt:</em></p>\n<ol class=\"fig-list\">\n<li><strong>Instrumentierung, Erfassung & Stimulierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>BSW/OS-Hooks und Compiler-Flags triggern synchron <code>Tracing_and_Profiling</code>.</li>\n<li>Interne Datenquellen und Scheduler initiieren die zyklische oder eventgetriebene Datenerfassung über <code>ECU_Data_Collection</code>.</li>\n<li>Netzwerktreiber spiegeln empfangene oder gesendete Kommunikationsrahmen über <code>Bus_Mirroring</code> an dedizierte Analyseports.</li>\n<li>Applikationscode und BSW rufen über APIs synchron Logging-Schnittstellen (z. B. <code>Dlt_SendLogMessage</code> / <code>ara::log</code>) auf.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Messung & Parametrierung:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Asynchrone XCP-DAQs/ODTs (<code>Measurement_and_Calibration</code>) tasten Variablen getriggert über OS-Raster (z. B. 1ms, 10ms) ab oder führen synchrone Parametermodifikationen über Page-Switching/Emulation aus.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Trace- und Datenexport:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Weiterleitung gepufferter Mess-, Trace-, Spiegel- und Diagnosedaten über Kommunikationsbusse (Ethernet/SOME/IP, CAN) oder dedizierte Schnittstellen an externe Kalibrier-, Test- und Entwicklungstools.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Plattform-Allokation:</strong></li>\n<li><strong>Classic Platform (CP):</strong> Realisierung über BSW-Module wie <code>Xcp</code>, <code>Dlt</code>, <code>Det</code>, <code>Mcu</code> sowie OS-Hooks (<code>PreTaskHook</code>, <code>PostTaskHook</code>) und ARTI-Instrumentation.</li>\n<li><strong>Adaptive Platform (AP):</strong> Realisierung primär über Functional Clusters (<code>ara::log</code>, ARTI/AP Execution Management Tracing, Core Dump Handling).</li>\n<li><strong>Footprint & Schedulability (SOP vs. DEV):</strong></li>\n<li>Entwicklungs-Features verursachen signifikanten Speicher- (RAM/ROM) und Laufzeit-Overhead sowie Intrusion-Effekte (Probe-Effect).</li>\n<li>Konfiguration muss über Pre-Compile-Schalter (<code>#define DLT_DEV_ERROR_DETECT STD_OFF</code>, Weglassen von XCP-Treibern) für Serien-Builds (SOP) vollständig deaktivierbar sein.</li>\n<li><strong>Security & Safety:</strong></li>\n<li>Kalibrier-, Debugging- und Logging-Interfaces exponieren ECU-Interne. Für Serienstände müssen Hardware-Debug-Ports (JTAG/SWD) physisch/elektronisch gesperrt und Protokolle (<code>FO_TR_FEAT_00120</code>) durch Security Access (Seed & Key) abgesichert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-8c2686c08b14a6fd", "to": "FIG-c5336c177608114a", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Kind-Feature <code>FO_TR_FEAT_00119</code> (<code>Timing_Analysis</code>) entfernt.</li>\n<li>Kind-Feature <code>FO_TR_FEAT_00269</code> (<code>Bus_Mirroring</code>) als optionales Sub-Feature ergänzt.</li>\n<li>Kind-Feature <code>FO_TR_FEAT_00263</code> (<code>ECU_Data_Collection</code>) als optionales Sub-Feature ergänzt.</li>\n<li>Position von <code>FO_TR_FEAT_00120</code> (<code>Measurement_and_Calibration</code>) von der ersten Position links ganz nach rechts verlagert.</li>\n</ul>"}]};
